static void printTriangle(int n) {
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= i; j++) {
            System.out.print("*");
        }
        System.out.println();
    }
}

public List<String> fizzBuzz(int n) {
    List<String> list = new ArrayList<>();
    for (int i = 1; i <= n; i++) {
        if (i % 15 == 0) {
            list.add("FizzBuzz");
        } else if (i % 3 == 0) {
            list.add("Fizz");
        } else if (i % 5 == 0) {
            list.add("Buzz");
        } else {
            list.add(Integer.toString(i));
        }
    }
    return list;
}

static int sumOfDigits(int n) {
    int sum = 0;
    int q = Math.abs(n);
    while(q>0){
        int p = q%10;
        sum +=p;
        q=q/10;
    }
    return sum;
}

static int reverse(int n) {
    int  t = 0;
    while(n!=0){
        int mod = n%10;
        if(t>Integer.MAX_VALUE/10 || t<Integer.MIN_VALUE/10){
            return 0;
        }
        t = (t*10)+mod;
        n=n/10;
    }
    return t;
}

static boolean isPrime(int n) {
    if(n<2){
        return false;
    }
    for(int i =2;i<=Math.sqrt(n);i++){
        if(n%i==0){
            return false;
        }
    }
    return true;
}
